+bool ShenandoahNMethod::handle_jumps(nmethod* nm) {
+  ShenandoahNMethod* data = gc_data(nm);
+  assert(data != nullptr, "Sanity");
+  assert(data->lock()->owned_by_self(), "Must hold the lock");
+
+  char gc_state = ShenandoahHeap::heap()->gc_state();
